_SIBLINGS = ("sources_facts", "sources_frontend", "sources_backend", "sources_database",
             "sources_hosting", "sources_services")


def _merge() -> dict:
    merged = dict(_BASE)
    for name in _SIBLINGS:
        try:
            mod = importlib.import_module(f"{__package__}.{name}")
        except ImportError as exc:
            if exc.name != f"{__package__}.{name}":
                raise  # the sibling exists but one of its own imports is broken
            continue
        for key, val in sorted(getattr(mod, "SOURCES", {}).items()):
            val = tuple(val)
            if key in merged and merged[key] != val:
                raise ValueError(f"duplicate source key {key!r} with different values ({name})")
            merged[key] = val
    return merged


SOURCES: dict = _merge()


def cite(keys):
    return [{"key": k, "title": SOURCES[k][0], "url": SOURCES[k][1], "accessed": SOURCES[k][2]}
            for k in keys if k in SOURCES]
